results.content:
for i in 3 4 5 6; do echo n$i > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
l=$(ls "$d/logs" | grep -c "^app.log.[0-9]"); [ "$l" = 3 ] || { echo "local keep: $l"; fail=1; }
[ ! -e "$d/logs/app.log.4" ] || { echo "app.log.4 remains"; fail=1; }
a=$(ls "$d/archive" | tr "\n" " ")
[ "$a" = "app.log.20261004 app.log.20261005 app.log.20261006 " ] || { echo "archive keep: $a"; fail=1; }
rm -rf "$d"
exit $fail

